<template><AppShell title="发布管理" back footer><view class="pad" style="background:#fff;padding-bottom:3px"><view class="segmented"><button class="ui-button" :class="{selected:kind==='SERVICE'}" @click="kind='SERVICE';load()">我的商品</button><button class="ui-button" :class="{selected:kind==='REQUEST'}" @click="kind='REQUEST';load()">我的求购</button></view></view><view class="tabs"><button class="ui-button" v-for="s in statuses" :key="s.value" :class="{selected:status===s.value}" @click="status=s.value;load()">{{s.label}}</button></view><view class="pad"><StateView :loading="loading" :error="error" :count="items.length" title="还没有发布" description="出售你的道具，或发布求购" @retry="load()" /><view v-for="item in items" :key="item.id" class="card"><view class="row"><GameArt variant="manage" class="mini-cover" :game="item.game" :src="images(item.images)[0]" /><view class="flex-1 stack"><view class="row between"><text class="bold">{{item.title}}</text><text class="tag" :class="{green:item.status==='ACTIVE',gray:item.status==='OFFLINE'}">{{labels[item.status]}}</text></view><text class="price">¥{{money(item.priceCents)}}<text class="tiny">{{item.pricingMode==='UNIT'?' / 件':' / 整批'}}</text></text><text v-if="item.pricingMode==='UNIT'" class="muted tiny">总量 {{item.quantity}} · 可售 {{item.availableQuantity}} · 预订 {{item.reservedQuantity}} · 已售 {{item.soldQuantity}}</text><text class="muted tiny">浏览 {{item.views}} · 完成 {{item.sales}} 单</text></view></view><text v-if="item.reviewNote" class="review-note">审核说明：{{item.reviewNote}}</text><view class="order-actions"><button v-if="!['RESERVED','MATCHED','SOLD'].includes(item.status)" class="ui-button btn outline small" @click="go(kind==='SERVICE'?'publish/service':'publish/index',{id:item.id})">编辑</button><button v-if="['ACTIVE','PENDING'].includes(item.status)" class="ui-button btn outline small" :disabled="busy" @click="action(item,'offline')">{{item.status==='PENDING'?'撤回':'下架'}}</button><button v-if="['OFFLINE','REJECTED'].includes(item.status)" class="ui-button btn small" :disabled="busy" @click="action(item,'resubmit')">重新提交审核</button><button v-if="['RESERVED','MATCHED','SOLD'].includes(item.status)" class="ui-button btn small" @click="go('orders/index',{role:'worker'})">查看相关订单</button></view></view><button v-if="items.length<total" class="ui-button load-more" @click="more">加载更多</button></view><template #footer><button class="ui-button btn wide" @click="go(kind==='SERVICE'?'publish/service':'publish/index')"><AppIcon class="app-icon" name="plus" />发布新{{kind==='SERVICE'?'道具':'求购'}}</button></template></AppShell></template>
<script setup>
import {ref} from 'vue';import {onLoad,onShow,onReachBottom} from '@dcloudio/uni-app';import AppShell from '../../components/AppShell.vue';import AppIcon from '../../components/AppIcon.vue';import GameArt from '../../components/GameArt.vue';import StateView from '../../components/StateView.vue';import {useList} from '../../lib/useList';import {request,requireLogin,go,money,images,labels,safely,confirm} from '../../lib/api';const kind=ref('SERVICE'),status=ref('ALL'),busy=ref(false),statuses=[{label:'全部',value:'ALL'},{label:'上架中',value:'ACTIVE'},{label:'审核中',value:'PENDING'},{label:'已下架',value:'OFFLINE'},{label:'未通过',value:'REJECTED'},{label:'已预订',value:'RESERVED'},{label:'已售出',value:'SOLD'}];const{items,total,loading,error,load,more}=useList('/boost/listings/mine',()=>({kind:kind.value,status:status.value}));onLoad(q=>kind.value=q.kind||'SERVICE');onShow(()=>{if(requireLogin())load()});onReachBottom(more);async function action(item,act){if(!await confirm(act==='offline'?'确定撤回或下架此发布？正在进行的订单不会取消。':'重新提交后需等待平台审核。'))return;busy.value=true;await safely(()=>request('/boost/listings/'+item.id+'/action','POST',{action:act}),'操作成功');busy.value=false;load()}
</script>
<style scoped>.review-note{display:block;color:#957746;font-size:12px;background:#fff9e9;border-radius:8px;padding:8px 10px;margin-top:12px}.card{padding:12px;margin-bottom:12px}.mini-cover{width:92px;height:92px}.card>.row{gap:10px}.card .bold{font-size:14px}.card .row.between{align-items:flex-start;gap:6px}.card .price{font-size:21px}.order-actions{justify-content:stretch;margin-top:10px}.order-actions .btn{flex:1}.card .tag{font-size:10px;flex-shrink:0}</style>
